/* All Tabs Menupopup */

.alltabs-item {
  &[selected] {
    font-weight: bold;
  }

  & > .menu-icon[srcset="null"] {
    content: var(--icon-folder);
    -moz-context-properties: fill, stroke;
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;
  }

  &[busy] > .menu-icon {
    content: url("chrome://messenger/skin/icons/hourglass.svg");
    -moz-context-properties: fill, stroke;
    fill: var(--selected-item-color);
    stroke: currentColor;

    @media (prefers-reduced-motion: no-preference) {
      content: var(--icon-loading);
      animation: alltabs-throbber-animation 1.05s steps(30) infinite;
      object-fit: cover;
      object-position: 0 0;
    }
  }
}

@keyframes alltabs-throbber-animation {
  100% {
    object-position: -480px 0;
  }
}
